examples.code:
const cityName = 'Калуга';
let population = 329000;

population = population + 1200;  // let позволяет переприсвоить
// cityName = 'Омск';            // а так нельзя: TypeError

document.body.append(cityName + ': ' + population);

const types = [
  typeof 42,          // 'number'
  typeof 'привет',    // 'string'
  typeof true,        // 'boolean'
  typeof undefined,   // 'undefined'
  typeof null,        // 'object' — легендарный баг языка
  typeof [1, 2],      // 'object': массив — частный случай объекта
];

document.body.append(types.join(' | '));

const priceString = '350';
const countString = '3';

const total = Number(priceString) * Number(countString); // 1050 — преобразовали сами
const auto = priceString * countString;                  // 1050 — JS преобразовал сам
const glued = priceString + countString;                 // '3503' — склейка строк!

document.body.append(total + ' | ' + auto + ' | ' + glued);

